void byValue(int x) { x += 100; }          // works on its own copy
void byRef(int& x) { x += 100; }           // alias: changes the caller's variable
size_t countA(const string& s) {           // alias, read-only, no copy
    return count(s.begin(), s.end(), 'a');
}

int main() {
    int a = 1, b = 1;
    byValue(a);
    byRef(b);
    cout << "after byValue: a = " << a << "\n";
    cout << "after byRef:   b = " << b << "\n";
    string big = "banana";
    cout << "a's in " << big << ": " << countA(big) << "\n";
    // const& also accepts a temporary made from a literal
    cout << "a's in alabama: " << countA("alabama") << "\n";
}

