    cout << boolalpha;
    int a = 1, b = 2;
    int& r = a;          // r is another name for a
    r = b;               // NOT re-binding: copies b's value into a
    cout << "after r = b: a=" << a << " b=" << b << "\n";
    cout << "r still aliases a: " << (&r == &a) << "\n";

    int* p = &a;
