    cout << "after p = &b; *p = 20: a=" << a << " b=" << b << "\n";

    int* none = nullptr; // a pointer may hold "nothing"; a reference cannot
    cout << "none is null: " << (none == nullptr) << "\n";
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    cout << boolalpha;
    vector<int> v;
    size_t lastCap = v.capacity();
    int reallocs = 0;
    cout << "push_back growth (size -> capacity when it changes)\n";
    for (int i = 1; i <= 20; i++) {
        v.push_back(i);
        if (v.capacity() != lastCap) {      // a reallocation just happened
            lastCap = v.capacity();
            reallocs++;
            cout << "size " << v.size() << " -> capacity " << lastCap << "\n";
        }
    }
    cout << "20 pushes, " << reallocs << " reallocations (geometric growth)\n";

    vector<int> w;
    w.reserve(20);                          // allocate once up front
    size_t cap = w.capacity();
    for (int i = 1; i <= 20; i++) w.push_back(i);
    cout << "with reserve(20): capacity unchanged = " << (w.capacity() == cap) << "\n";
    cout << "size=" << w.size() << " capacity=" << w.capacity() << "\n";
}

