void f(int) { cout << "f(int)\n"; }
void f(double) { cout << "f(double)\n"; }
void f(bool) { cout << "f(bool)\n"; }
void f(const string&) { cout << "f(const string&)\n"; }

int main() {
    cout << "f(7):           "; f(7);              // exact match
    cout << "f('a'):         "; f('a');            // char -> int is a promotion
    cout << "f(2.5f):        "; f(2.5f);           // float -> double is a promotion
    cout << "f(2.5):         "; f(2.5);            // exact match
    cout << "f(\"hi\"):        "; f("hi");         // pointer -> bool (standard conversion)
    cout << "f(string(\"hi\")): "; f(string("hi"));  // exact match
    // "hi" -> string would be a user-defined conversion, which ranks lower than pointer -> bool
}

