#include <bits/stdc++.h>
using namespace std;

long long sumRec(int n) {            // each call adds a frame: depth n
    return n == 0 ? 0 : n + sumRec(n - 1);
}

int main() {
    cout << "recursive sum 1..10000 = " << sumRec(10000) << "\n";  // 10000 frames: fine

    // A chain of 1,000,000 nodes: node i points to i+1
    int n = 1000000;
    vector<int> next(n, -1);
    for (int i = 0; i + 1 < n; i++) next[i] = i + 1;

    // Same walk with an explicit stack on the heap: no deep call stack needed
    vector<int> st = {0};
    long long visited = 0;
    while (!st.empty()) {
        int u = st.back();
        st.pop_back();
        visited++;
        if (next[u] != -1) st.push_back(next[u]);
    }
    cout << "iterative walk visited " << visited << " nodes\n";
    // Recursing 1,000,000 deep would use tens of MB of stack and overflow an 8 MB stack.
}

