int main() {
    cout << boolalpha;
    vector<int> v = {1, 2, 3};
    for (auto x : v) x *= 2;                 // x is a copy: v unchanged
    cout << "range-for by value:  ";
    for (int x : v) cout << x << " ";
    for (auto& x : v) x *= 2;                // reference: really modifies
    cout << "\nrange-for by ref:    ";
    for (int x : v) cout << x << " ";

    vector<int> empty;
    cout << "\nempty.size() - 1 = " << empty.size() - 1 << "   (unsigned wrap-around)\n";
    int i = -1;
    cout << "-1 < v.size():  " << (i < (long long)v.size()) << " with signed types\n";
    cout << "-1 < size_t(3): " << (size_t(i) < v.size()) << " (-1 became a huge unsigned)\n";

    cout << "safe backwards:     ";
    for (size_t k = v.size(); k-- > 0;) cout << v[k] << " ";   // works for empty too
    cout << "\n";
}

