    int c[3] = {1, 2, 3};                  // C array: no copy with =, no size once passed
    array<int, 3> a = {1, 2, 3};           // knows its size, copyable, comparable
    vector<int> v = {1, 2, 3};             // growable, elements on the heap

    array<int, 3> b = a;                   // real copy
