    cout << "a[0]=" << a[0] << " b[0]=" << b[0] << " (independent copies)\n";
    cout << "a == b: " << (a == b) << "\n";
    cout << "sizeof(array<int,3>) == 3*sizeof(int): " << (sizeof(a) == 3 * sizeof(int)) << "\n";
    cout << "c.size via sizeof: " << sizeof(c) / sizeof(c[0]) << ", a.size(): " << a.size() << "\n";

    v.push_back(4);
    cout << "vector grew to size " << v.size() << "\n";
    try {
        a.at(5) = 1;                       // checked access throws
    } catch (const out_of_range&) {
        cout << "a.at(5) threw out_of_range\n";
    }
}

#include <bits/stdc++.h>
