// true if the characters live inside the string object itself (SSO)
bool inside(const string& s) {
    const char* p = s.data();
    const char* lo = reinterpret_cast<const char*>(&s);
    return p >= lo && p < lo + sizeof(string);
}

int main() {
    cout << boolalpha;
    string small = "hello";
    string big(60, 'x');
    cout << "small string stored inside the object: " << inside(small) << "\n";
    cout << "60-char string stored inside the object: " << inside(big) << "\n";

    string s("ab\0cd", 5);                 // std::string may contain '\0'
    cout << "std::string size(): " << s.size() << "\n";
    cout << "strlen of c_str():  " << strlen(s.c_str()) << "  (stops at the first \\0)\n";

    string e = "\xC3\xA9";                 // the UTF-8 bytes of the letter e-acute
    cout << "size of the 1-letter UTF-8 string: " << e.size() << " bytes\n";
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    cout << boolalpha;
    int n = 50000;
    string slow, fast;
    long long copied = 0;                  // characters copied by s = s + c
    for (int i = 0; i < n; i++) {
        copied += slow.size();             // s + c copies all of s into a temporary
        slow = slow + 'a';
    }
    int reallocs = 0;
    size_t cap = fast.capacity();
    for (int i = 0; i < n; i++) {
        fast += 'a';                       // appends in place
        if (fast.capacity() != cap) { cap = fast.capacity(); reallocs++; }
    }
    cout << "n = " << n << ", same result: " << (slow == fast) << "\n";
    cout << "s = s + c copied about " << copied << " characters (n^2/2)\n";
    cout << "s += c reallocated only " << reallocs << " times (O(n) total)\n";

    string r;
    r.reserve(n);                          // known size: allocate once
    for (int i = 0; i < n; i++) r.push_back('a');
    cout << "reserve + push_back kept capacity: " << (r.capacity() == (size_t)n) << "\n";
}

#include <bits/stdc++.h>
using namespace std;

string describe(int month) {
    string s;
    switch (month) {
        case 12: case 1: case 2: s = "winter"; break;
        case 3: s = "spring ";
            [[fallthrough]];               // intentional: also add the next line
        case 4: s += "(early-year season)"; break;
        default: s = "other";
    }
    return s;
}

int main() {
    for (int m : {1, 3, 4, 7}) cout << "month " << m << ": " << describe(m) << "\n";

    int grid[3][3] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    // break only leaves the inner loop; a lambda with return leaves both
    auto find = [&](int target) {
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++)
                if (grid[i][j] == target) { cout << "found " << target << " at (" << i << "," << j << ")\n"; return true; }
        return false;
    };
    find(6);
    cout << "find 10: " << boolalpha << find(10) << "\n";
    for (int i = 0; i < 5; i++) {
        if (i % 2 == 0) continue;          // skips the rest, the i++ still runs
        cout << "odd " << i << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    cout << boolalpha;
    vector<int> v = {1, 2};
    cout << "size " << v.size() << " capacity " << v.capacity() << "\n";
    const int* old = v.data();             // address of the buffer before growing
    v.push_back(3);                        // no room: new buffer, old one freed
    cout << "buffer moved after push_back: " << (old != v.data()) << "\n";
    cout << "(a reference r = v[0] taken before would now dangle; we never read it)\n";

    vector<int> w = {1, 2};
    w.reserve(10);                         // make room first
    const int* before = w.data();
    int& r = w[0];                         // safe: no reallocation will happen
    w.push_back(3);
    cout << "buffer moved with reserve: " << (before != w.data()) << ", r = " << r << "\n";

    size_t idx = 0;                        // indices survive reallocation
    v.push_back(4);
    cout << "v[idx] after more pushes: " << v[idx] << "\n";
}

#include <bits/stdc++.h>
using namespace std;

struct Stats { int mn, mx; double avg; };

Stats stats(const vector<int>& v) {        // named struct: self-documenting
    return {*min_element(v.begin(), v.end()), *max_element(v.begin(), v.end()),
            accumulate(v.begin(), v.end(), 0.0) / v.size()};
}
pair<int, int> minmax(const vector<int>& v) {   // quick pair for a helper
    auto [a, b] = minmax_element(v.begin(), v.end());
    return {*a, *b};
}
optional<int> indexOf(const vector<int>& v, int x) {  // result may be absent
    auto it = find(v.begin(), v.end(), x);
    if (it == v.end()) return nullopt;
    return it - v.begin();
}
void minMaxOut(const vector<int>& v, int& mn, int& mx) {  // out-parameters
    mn = *min_element(v.begin(), v.end());
    mx = *max_element(v.begin(), v.end());
}

int main() {
    vector<int> v = {4, 1, 9, 3};
    auto [mn, mx, avg] = stats(v);         // structured bindings
    cout << "stats: min=" << mn << " max=" << mx << " avg=" << avg << "\n";
    auto p = minmax(v);
    cout << "pair: " << p.first << " " << p.second << "\n";
    cout << "indexOf 9: " << indexOf(v, 9).value() << "\n";
    cout << "indexOf 5 has value: " << boolalpha << indexOf(v, 5).has_value() << "\n";
    int a, b;
    minMaxOut(v, a, b);
    cout << "out params: " << a << " " << b << "\n";
}
